CREATE TABLE 학생 (
  학번 NUMBER(6) PRIMARY KEY,
  이름 VARCHAR2(30 CHAR) NOT NULL,
  학년 NUMBER(1) DEFAULT 1 CHECK (학년 BETWEEN 1 AND 4)
);

CREATE TABLE 시험성적 (
  번호 NUMBER PRIMARY KEY,
  이름 VARCHAR2(30 CHAR) NOT NULL,
  점수 NUMBER NOT NULL,
  CONSTRAINT CHK_점수 CHECK (점수 BETWEEN 0 AND 100)
);

SELECT 지역, 과목, SUM(금액) AS 합계
FROM 매출 GROUP BY ROLLUP(지역,과목)
ORDER BY 지역 NULLS LAST, 과목 NULLS LAST;

SELECT 학번,이름,DB,JAVA FROM (SELECT 학번,이름,과목,점수 FROM 성적)
PIVOT(SUM(점수) FOR 과목 IN ('DB' AS DB,'JAVA' AS JAVA))
ORDER BY 학번;

SELECT 학번,이름,과목,점수 FROM 가로성적
UNPIVOT(점수 FOR 과목 IN (DB AS 'DB',JAVA AS 'JAVA'))
ORDER BY 학번,과목;

UPDATE 계좌 SET 잔액=잔액-100 WHERE 계좌ID=1;
SAVEPOINT s1;
UPDATE 계좌 SET 잔액=잔액+200 WHERE 계좌ID=1;
ROLLBACK TO s1;
COMMIT;
SELECT 계좌ID,이름,잔액 FROM 계좌;

UPDATE 계좌 SET 잔액=잔액-100 WHERE 계좌ID=1;
UPDATE 계좌 SET 잔액=잔액+100 WHERE 계좌ID=2;
SELECT 계좌ID,이름,잔액 FROM 계좌 ORDER BY 계좌ID;
